import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int to, id, weight;

        Edge(int to, int id, int weight) {
            this.to = to;
            this.id = id;
            this.weight = weight;
        }
    }

    static class State implements Comparable<State> {
        int vertex;
        long distance;

        State(int vertex, long distance) {
            this.vertex = vertex;
            this.distance = distance;
        }

        public int compareTo(State other) {
            return Long.compare(distance, other.distance);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int stations = fs.nextInt();
        int railCount = fs.nextInt();

        @SuppressWarnings("unchecked")
        ArrayList<Edge>[] graph = new ArrayList[stations];
        for (int i = 0; i < stations; i++) graph[i] = new ArrayList<>();

        int[] edgeU = new int[railCount];
        int[] edgeV = new int[railCount];
        int[] edgeW = new int[railCount];

        for (int id = 0; id < railCount; id++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            int w = fs.nextInt();

            edgeU[id] = a;
            edgeV[id] = b;
            edgeW[id] = w;
            graph[a].add(new Edge(b, id, w));
            graph[b].add(new Edge(a, id, w));
        }

        boolean[] bridge = new boolean[railCount];
        int[] discovery = new int[stations];
        int[] low = new int[stations];
        int[] parent = new int[stations];
        int[] parentEdge = new int[stations];
        int[] nextEdge = new int[stations];
        int[] stack = new int[stations];
        Arrays.fill(parent, -1);
        Arrays.fill(parentEdge, -1);

        int timer = 0;
        for (int start = 0; start < stations; start++) {
            if (discovery[start] != 0) continue;

            int top = 0;
            stack[0] = start;
            discovery[start] = low[start] = ++timer;

            while (top >= 0) {
                int v = stack[top];

                if (nextEdge[v] < graph[v].size()) {
                    Edge e = graph[v].get(nextEdge[v]++);
                    if (e.id == parentEdge[v]) continue;

                    if (discovery[e.to] == 0) {
                        parent[e.to] = v;
                        parentEdge[e.to] = e.id;
                        discovery[e.to] = low[e.to] = ++timer;
                        stack[++top] = e.to;
                    } else {
                        low[v] = Math.min(low[v], discovery[e.to]);
                    }
                } else {
                    top--;
                    if (parent[v] != -1) {
                        int p = parent[v];
                        low[p] = Math.min(low[p], low[v]);
                        if (low[v] > discovery[p]) {
                            bridge[parentEdge[v]] = true;
                        }
                    }
                }
            }
        }

        int[] component = new int[stations];
        Arrays.fill(component, -1);
        int[] queue = new int[stations];
        int componentCount = 0;

        for (int start = 0; start < stations; start++) {
            if (component[start] != -1) continue;

            int head = 0, tail = 0;
            queue[tail++] = start;
            component[start] = componentCount;

            while (head < tail) {
                int v = queue[head++];
                for (Edge e : graph[v]) {
                    if (bridge[e.id] || component[e.to] != -1) continue;
                    component[e.to] = componentCount;
                    queue[tail++] = e.to;
                }
            }
            componentCount++;
        }

        long[] perimeter = new long[componentCount];
        int[] componentEdges = new int[componentCount];
        for (int id = 0; id < railCount; id++) {
            if (!bridge[id]) {
                int c = component[edgeU[id]];
                perimeter[c] += edgeW[id];
                componentEdges[c]++;
            }
        }

        int queries = fs.nextInt();
        StringBuilder output = new StringBuilder();

        for (int qi = 0; qi < queries; qi++) {
            int start = fs.nextInt() - 1;
            long trainLength = fs.nextInt();

            long[] dist = new long[stations];
            Arrays.fill(dist, Long.MAX_VALUE);
            dist[start] = 0;

            PriorityQueue<State> pq = new PriorityQueue<>();
            pq.add(new State(start, 0));

            while (!pq.isEmpty()) {
                State current = pq.poll();
                if (current.distance != dist[current.vertex]) continue;

                for (Edge e : graph[current.vertex]) {
                    long nd = current.distance + e.weight;
                    if (nd < dist[e.to]) {
                        dist[e.to] = nd;
                        pq.add(new State(e.to, nd));
                    }
                }
            }

            long answer = Long.MAX_VALUE;
            for (int v = 0; v < stations; v++) {
                int c = component[v];
                if (componentEdges[c] > 0 && perimeter[c] >= trainLength) {
                    answer = Math.min(answer, 2 * dist[v] + perimeter[c]);
                }
            }

            output.append(answer == Long.MAX_VALUE ? -1 : answer).append('\n');
        }

        System.out.print(output);
    }
}
